dashboard.definition:
{
  "title": "Sites",
  "description": "Site health from New Central: worst sites first, trend and all sites.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "tr",
        "defaultValue": "-24h,now"
      }
    },
    "input_site": {
      "type": "input.text",
      "title": "Site (wildcard)",
      "options": {
        "token": "site",
        "defaultValue": "*"
      }
    }
  },
  "dataSources": {
    "ds_rank": {
      "type": "ds.search",
      "name": "Worst sites",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\" earliest=-30m\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(health.groups{}.name) as hn latest(health.groups{}.value) as hv latest(devices.count) as devices latest(clients.count) as clients latest(alerts.totalCount) as alerts latest(reasons{}.reason) as reasons latest(_time) as last_poll by id siteName\n| eval poor=tonumber(mvindex(hv,mvfind(hn,\"Poor\"))), fair=tonumber(mvindex(hv,mvfind(hn,\"Fair\"))), good=tonumber(mvindex(hv,mvfind(hn,\"Good\")))\n| eval poor=coalesce(poor,0), fair=coalesce(fair,0), good=coalesce(good,0)\n| where devices>0\n| eval Reasons=mvjoin(reasons,\", \")\n| sort - poor - alerts\n| table siteName poor fair good devices clients alerts Reasons\n| rename siteName as Site, poor as \"Poor\", fair as \"Fair\", good as \"Good\", devices as Devices, clients as Clients, alerts as Alerts"
      }
    },
    "ds_trend": {
      "type": "ds.search",
      "name": "Poor health trend",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\"\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| eval poor=tonumber(mvindex('health.groups{}.value',mvfind('health.groups{}.name',\"Poor\"))), devices='devices.count'\n| where devices>0\n| timechart minspan=15m max(poor) by siteName limit=8"
      }
    },
    "ds_sites": {
      "type": "ds.search",
      "name": "Sites",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\" earliest=-30m\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(health.groups{}.name) as hn latest(health.groups{}.value) as hv latest(devices.count) as devices latest(clients.count) as clients latest(alerts.totalCount) as alerts latest(reasons{}.reason) as reasons latest(_time) as last_poll by id siteName\n| eval poor=tonumber(mvindex(hv,mvfind(hn,\"Poor\"))), fair=tonumber(mvindex(hv,mvfind(hn,\"Fair\"))), good=tonumber(mvindex(hv,mvfind(hn,\"Good\")))\n| eval poor=coalesce(poor,0), fair=coalesce(fair,0), good=coalesce(good,0)\n| eval last_poll=strftime(last_poll,\"%Y-%m-%d %H:%M:%S\")\n| table siteName id clients devices alerts last_poll\n| sort - clients"
      }
    }
  },
  "visualizations": {
    "v_rank": {
      "type": "splunk.table",
      "title": "Sites ranked by poor health (values as reported by the API)",
      "dataSources": {
        "primary": "ds_rank"
      },
      "options": {
        "count": 8
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/aruba_central_poc/alerts?form.site=$row.Site.value$&form.severity=*",
            "newTab": false
          }
        }
      ]
    },
    "v_trend": {
      "type": "splunk.line",
      "title": "Poor health over time (top 8 sites)",
      "dataSources": {
        "primary": "ds_trend"
      },
      "options": {
        "x": "> primary | seriesByName('_time')",
        "legendDisplay": "bottom",
        "y": "> primary | frameBySeriesTypes('number')",
        "nullValueDisplay": "gaps"
      }
    },
    "v_sites": {
      "type": "splunk.table",
      "title": "All sites",
      "dataSources": {
        "primary": "ds_sites"
      },
      "options": {
        "count": 10
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/aruba_central_poc/alerts?form.site=$row.siteName.value$&form.severity=*",
            "newTab": false
          }
        }
      ]
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$"
          }
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_time",
      "input_site"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "type": "absolute",
        "options": {
          "width": 1200,
          "height": 1030
        },
        "structure": [
          {
            "item": "v_rank",
            "type": "block",
            "position": {
              "x": 0,
              "y": 0,
              "w": 1200,
              "h": 330
            }
          },
          {
            "item": "v_trend",
            "type": "block",
            "position": {
              "x": 0,
              "y": 350,
              "w": 1200,
              "h": 300
            }
          },
          {
            "item": "v_sites",
            "type": "block",
            "position": {
              "x": 0,
              "y": 670,
              "w": 1200,
              "h": 340
            }
          }
        ]
      }
    },
    "options": {
      "submitButton": false
    },
    "tabs": {
      "items": [
        {
          "layoutId": "layout_1",
          "label": "Sites"
        }
      ]
    }
  }
}
